.darma-loader-snake-trail {
  position: relative;
  width: 48px;
  height: 48px;
}
.darma-loader-snake-trail i {
  position: absolute;
  top: 0;
  left: 0;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-snake-trail-track 2s linear infinite;
}
.darma-loader-snake-trail i:nth-child(1) { animation-delay: 0s; opacity: 1; }
.darma-loader-snake-trail i:nth-child(2) { animation-delay: -0.14s; opacity: 0.82; }
.darma-loader-snake-trail i:nth-child(3) { animation-delay: -0.28s; opacity: 0.64; }
.darma-loader-snake-trail i:nth-child(4) { animation-delay: -0.42s; opacity: 0.46; }
.darma-loader-snake-trail i:nth-child(5) { animation-delay: -0.56s; opacity: 0.3; }
@keyframes darma-loader-snake-trail-track {
  0% { top: 0; left: 0; }
  25% { top: 0; left: calc(100% - 10px); }
  50% { top: calc(100% - 10px); left: calc(100% - 10px); }
  75% { top: calc(100% - 10px); left: 0; }
  100% { top: 0; left: 0; }
}

